pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address and the block timestamp to influence the pseudo-randomness
    function testFuzz_property(address caller, uint256 ts) public {
        // keep caller non-zero and distinct from contract/bank
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // bound timestamp to a reasonable range to avoid overflow in vm.warp
        ts = bound(ts, 1, type(uint64).max);

        // fund the caller so it can send the ticket amount
        uint256 ticket = 10; // must match contract constant TICKET_AMOUNT
        vm.deal(caller, ticket);

        // set the block timestamp to the fuzzed value to influence randomness
        vm.warp(ts);

        // perform the play call as the fuzzed caller sending exactly the ticket amount
        vm.prank(caller);
        try c.play{value: ticket}() {
            // call succeeded
        } catch {
            // call reverted (shouldn't for well-formed inputs), treat as non-success
        }

        // The universal property we assert: after any admissible play call (exact ticket sent by any caller),
        // the pot value returned by the reference implementation is either 0 or equals the accumulated pot.
        // Concretely we assert that pot is either 0 or >= ticket (i.e., play never leaves pot in an invalid small state).
        // This distinguishes the mutant because inverting the branch can clear pot at different randomness values
        // causing some fuzzed inputs to make pot==0 when reference would have left pot>=ticket (or vice versa).

        // Single assertion reading c's public getter
        uint256 p = c.pot();
        assertTrue(p == 0 || p >= ticket);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameters: an address that will call play, and a timestamp to influence RNG
    function testFuzz_property(address caller, uint256 ts) public {
        // Keep caller as a non-zero address and not the contract deployer (bank) to be general
        vm.assume(caller != address(0));
        // ensure caller is not the bank (deployer) to avoid any accidental privileged behavior
        vm.assume(caller != address(this));

        // bound timestamp to a reasonable uint32-range to keep block.timestamp realistic
        uint256 timestamp = bound(ts, 1, type(uint32).max);

        // fund caller so it can send the ticket
        vm.deal(caller, C.TICKET_AMOUNT());

        // record pot before
        uint256 beforePot = c.pot();

        // advance block timestamp to the fuzzed value to influence RNG
        vm.warp(timestamp);

        // perform the call as the fuzzed caller sending exactly TICKET_AMOUNT
        vm.prank(caller);
        c.play{value: C.TICKET_AMOUNT()}();

        // After the call, the reference contract's invariant (property) is:
        // pot is either incremented by TICKET_AMOUNT (if RNG != 0) or reset to 0 (if RNG == 0).
        // Concretely: when RNG != 0, pot must equal beforePot + TICKET_AMOUNT.
        // The mutant inverts the RNG check so there exist caller/timestamp pairs where the mutant
        // clears the pot while the reference does not, making pot() differ.
        // We assert the universal property that whenever the RNG (computed by the contract) is != 0,
        // the pot increases by TICKET_AMOUNT; this holds for the reference for all inputs and
        // will fail on the mutant for some inputs.

        // Recompute the RNG locally using the same expression as in the contract to decide which branch
        uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, caller))) % 2;

        if (random != 0) {
            // In the correct contract C, when random != 0 the payout branch does NOT run,
            // so pot must have increased by exactly TICKET_AMOUNT.
            assertTrue(c.pot() == beforePot + C.TICKET_AMOUNT());
        } else {
            // When random == 0, the correct contract pays out and clears the pot to 0.
            assertTrue(c.pot() == 0);
        }
    }
}

