pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameter: an address to act as the player
    function testFuzz_property(address player) public {
        // keep player a non-zero address
        vm.assume(player != address(0));

        // ensure player has enough balance to pay the ticket
        uint256 ticket = 10;
        vm.deal(player, ticket);

        // The property concerns the pot after a winning play. We cannot force randomness,
        // but we can run the call repeatedly until a win occurs; the reference contract
        // should always reset pot to 0 after a win. The mutant sometimes leaves pot == 1.
        // To keep this a single-call observable property, we perform the single call and
        // then assert that if the pot is non-zero after the call then it must equal the
        // ticket contributed (i.e., no residual leftover after a winning payout). However,
        // simpler and precise: after a winning payout the reference guarantees pot==0.
        // We detect a win by observing that the player's balance increased by more than 0
        // (they received the payout). We perform the call and then check: if the player
        // received a payout, then pot == 0. This holds for the reference for all inputs
        // and is violated by the mutant when it leaves pot == FEE_AMOUNT.

        // Record balances before
        uint256 beforePlayer = player.balance;
        uint256 beforeBank = c.bank();
        uint256 beforePot = c.pot();

        // make the single play call
        vm.prank(player);
        c.play{value: ticket}();

        // balances after
        uint256 afterPlayer = player.balance;
        uint256 afterPot = c.pot();

        // Determine whether the player received a payout: afterPlayer > beforePlayer - ticket
        // (because they paid ticket, and if they won they got pot - fee back, increasing net balance)
        bool playerGained = (afterPlayer > beforePlayer - ticket);

        // The invariant (reference): if playerGained then pot == 0. The mutant can leave pot == 1
        // after a winning call, violating this.
        assertTrue(!playerGained || afterPot == 0);
    }
}

