pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: caller address and an arbitrary uint64 to influence block.timestamp/difficulty via vm.warp/vm.roll
    function testFuzz_property(address player, uint64 timeOffset) public {
        // admissible domain: player should be a non-zero address and not the contract deployer (bank)
        vm.assume(player != address(0));
        vm.assume(player != address(this));

        // The ticket and fee constants from the contract (known values)
        uint256 TICKET = 10;
        uint256 FEE = 1;

        // Give the player enough ETH
        vm.deal(player, 1 ether);

        // Set block timestamp to a value influenced by the fuzzed timeOffset to allow randomness to vary
        // Keep it wide but deterministic per fuzz input
        vm.warp(uint256(timeOffset));

        // Make a call as player sending exactly the ticket amount
        vm.prank(player);
        // We call play and we want to know whether the call succeeded (it should) and then check pot
        // Use try/catch to ensure we proceed even if unexpected revert happens
        bool ok;
        try c.play{value: TICKET}() {
            ok = true;
        } catch {
            ok = false;
        }

        // We only consider successful plays (require(msg.value == TICKET) should make them succeed)
        vm.assume(ok);

        // The general invariant: after any successful play that results in a payout (i.e., the contract paid out the pot and thus reduced its balance), the reference contract always sets pot to 0.
        // We detect whether a payout happened by checking that the contract balance is strictly less than the ticket amount just contributed plus previous pot.
        // However, since we don't know previous pot, a straightforward and reliable universal property is:
        // If the contract's pot() is non-zero after the call, then that means the mutant left a residual pot (FEE) after a payout — the reference never does this.
        // Therefore the reference satisfies: after any successful play(), c.pot() == 0 whenever the contract's balance is less than or equal to its pot expectation after a payout.
        // To keep the admissible domain wide and avoid relying on exact balance arithmetic, assert the known true universal fact for the reference: after any successful play() sending exactly TICKET, c.pot() is either 0 (normal) or equals the contributed TICKET (if no payout occurred). But in the reference, after a successful play() c.pot() != FEE.

        // Simpler direct invariant that the reference always satisfies for all admissible inputs:
        // After any successful play() sending exactly TICKET, c.pot() != FEE.
        // The mutant breaks this by setting pot = FEE after a winning payout.

        assertTrue(c.pot() != FEE);
    }
}

