import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz two distinct player addresses to produce a sequence that can show accumulation when pot isn't reset
    function testFuzz_property(address player1, address player2) public {
        // admissible domain: distinct players, nonzero addresses
        vm.assume(player1 != address(0));
        vm.assume(player2 != address(0));
        vm.assume(player1 != player2);

        uint ticket = 10;

        // fund both players so they can pay the ticket
        vm.deal(player1, 1 ether);
        vm.deal(player2, 1 ether);

        // First play by player1
        vm.prank(player1);
        c.play{value: ticket}();

        // Second play by player2
        vm.prank(player2);
        c.play{value: ticket}();

        // After any single completed call to play, the reference ensures contract balance is at most the ticket amount.
        // Here we assert the universal property by checking address(c).balance <= ticket.
        // This holds for the reference for ALL admissible inputs; the mutant (which doesn't reset pot) can leave balance > ticket for some inputs and so will fail this assertion.
        assertTrue(address(c).balance <= ticket);
    }
}

