pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz the caller address and an initial pot seed by having the caller play multiple times to accumulate pot.
    // We will then trigger a play() and assert that whenever the caller wins (we can't control randomness),
    // the reference pays out exactly previous pot_before_play + ticket - FEE to the winner, leaving pot == 0.
    // To make this deterministic for checking, we exploit that the only observable violation between P and M
    // is the amount transferred to the winner when they win; we fuzz the caller and the number of prior contributions.
    function testFuzz_property(address caller, uint8 priorPlays) public {
        // admissible bounds: caller must not be zero and must be a distinct EOA
        vm.assume(caller != address(0));
        // bound number of prior plays to a smallish number to keep balances reasonable
        priorPlays = uint8(bound(priorPlays, 0, 10));

        uint ticket = 10;
        uint fee = 1;

        // fund the caller so they can play multiple times
        vm.deal(caller, 1000 ether);

        // Have caller perform `priorPlays` plays to build up pot deterministically
        for (uint i = 0; i < priorPlays; i++) {
            vm.prank(caller);
            c.play{value: ticket}();
        }

        // Record pot before the decisive play via the public getter
        uint potBefore = c.pot();

        // Record caller balance before the decisive play
        uint balBefore = caller.balance;

        // Make the decisive play from caller
        vm.prank(caller);
        // We cannot control randomness; we perform the play and then observe results.
        // Use try/catch pattern to ensure we capture success vs revert (play should not revert here).
        bool ok;
        try c.play{value: ticket}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: if the call succeeded and the caller won, then the caller's balance must have
        // increased by exactly (potBefore + ticket - fee). We cannot directly know if caller won from return,
        // but we can detect a win because when a win happens the contract sets pot to zero. Thus:
        // If after the call c.pot() == 0 then a win occurred and caller must have received potBefore + ticket - fee.

        // Compute caller balance delta and observe pot after
        uint balAfter = caller.balance;
        uint potAfter = c.pot();

        // If a win happened (potAfter == 0) then the winner payout must equal potBefore + ticket - fee.
        // The single assertion below expresses that universal property: whenever the contract reports pot==0
        // after the play, the caller's balance increased by potBefore + ticket - fee.
        assertTrue(!(potAfter == 0) || (balAfter == balBefore + (potBefore + ticket - fee)));
    }
}

