pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz the caller address (as an EOA) and a seed-influencing nonce to vary block.timestamp slightly via vm.warp.
    // The admissible domain: actor must not be zero and must have enough balance to pay the ticket.
    function testFuzz_property(address actor, uint256 timeWarp) public {
        // keep actor usable
        vm.assume(actor != address(0));
        // bound the time warp to a reasonable range so we still explore variability
        timeWarp = bound(timeWarp, 0, 1000000);

        uint256 TICKET = 10;
        uint256 FEE = 1;

        // fund the actor so they can buy a ticket
        vm.deal(actor, 1 ether);

        // Capture pot and balances before the call
        uint256 pot_before = c.pot();
        uint256 c_balance_before = address(c).balance;
        uint256 actor_balance_before = actor.balance;

        // Warp time to alter the deterministic randomness source
        vm.warp(block.timestamp + int256(timeWarp));

        // Make the call from actor paying exactly the ticket amount
        vm.prank(actor);
        // we perform a low-level try/catch to observe whether call reverts (it should not for correct inputs)
        bool ok;
        try c.play{value: TICKET}() {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call reverted, it violated the precondition (shouldn't for valid ticket amount). The reference never reverts here.
        // Restrict to admissible runs where the call succeeded so we reason about payouts.
        vm.assume(ok);

        // After call observe new balances and pot
        uint256 pot_after = c.pot();
        uint256 c_balance_after = address(c).balance;
        uint256 actor_balance_after = actor.balance;

        // The general rule (for the reference C): if a payout occurred (i.e., pot_before+TICKET was paid out), then pot_after == 0
        // and the caller's balance increased exactly by (pot_before + TICKET - FEE) when the contract's random chose the payout branch.
        // Because randomness depends on block.timestamp/block.difficulty/msg.sender, not all fuzz runs will trigger payout.
        // We therefore check the implication: whenever pot_after == 0 and the contract's balance decreased accordingly,
        // the actor's balance gain equals pot_before + TICKET - FEE.

        // Compute observed changes
        uint256 contract_delta = c_balance_before >= c_balance_after ? c_balance_before - c_balance_after : 0;
        uint256 actor_gain = actor_balance_after >= actor_balance_before ? actor_balance_after - actor_balance_before : 0;

        // We assert the universal property: if the contract's pot became zero after the call and the contract lost funds
        // (indicating a payout happened), then the caller received exactly pot_before + TICKET - FEE.
        // This holds for the reference C for all admissible inputs, but the mutant that increments pot before payout
        // will in some runs cause actor_gain to be larger by 1, breaking the assertion for some fuzz input.
        if (pot_after == 0 && contract_delta > 0) {
            assertTrue(actor_gain == pot_before + TICKET - FEE);
        } else {
            // If no payout occurred, just assert that the contract's pot increased by TICKET and balances reflect that
            // (either because random!=0 so pot accumulates, or some other non-payout path). For reference this should hold.
            assertTrue(pot_after == pot_before + TICKET);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller address and a warp delta to influence block.timestamp used in randomness
    function testFuzz_property(address caller, uint256 timeWarp) public {
        // keep caller non-zero and distinct from contract deployer to be realistic
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // bound timeWarp to a reasonable range to avoid overflow when adding to block.timestamp
        timeWarp = bound(timeWarp, 0, 1 days);

        // fund the caller so they can send the ticket amount
        uint256 ticket = 10;
        vm.deal(caller, 1 ether);

        // record balances and pot before call
        uint256 beforeCaller = caller.balance;
        uint256 beforeContract = address(c).balance;
        uint256 beforePot = c.pot();

        // shift time to influence randomness (fuzzer will try values)
        vm.warp(block.timestamp + timeWarp);

        // perform the play call as the caller sending exactly the ticket amount
        vm.prank(caller);
        c.play{value: ticket}();

        // After a winning payout (random==0) the reference contract guarantees the caller
        // receives exactly (pot_before + ticket) - FEE_AMOUNT and contract.balance decreases accordingly,
        // and c.pot == 0. We observe this by checking: if contract pot is zero after the call,
        // then caller's balance increased by (beforePot + ticket - 1) and contract balance decreased by same amount.
        // This is a single assertion reading c's public surface and balances.

        bool ok;
        if (c.pot() == 0) {
            // caller got payout (winner case); compute expected delta per reference: (beforePot + ticket - fee)
            uint256 expectedDelta = beforePot + ticket - 1;
            uint256 actualCallerDelta = caller.balance - beforeCaller;
            uint256 actualContractDelta = beforeContract - address(c).balance;
            // both deltas must equal expectedDelta; combine into single boolean
            ok = (actualCallerDelta == expectedDelta) && (actualContractDelta == expectedDelta);
        } else {
            // if pot not zero, then no payout happened; caller simply paid the ticket so contract balance increased by ticket
            ok = (address(c).balance - beforeContract == ticket) && (c.pot() == beforePot + ticket);
        }

        // single assertion: the correct contract satisfies this for all inputs; the mutant that increments pot before payout
        // will for some inputs (when payout occurred) make actualCallerDelta larger than expectedDelta and therefore fail this assert
        assertTrue(ok);
    }
}
